+        int components = 0;
+
+        for (int i = 0; i < graph.getVertexCount(); i++) {
+            if (!visitedArray[i]) {
+                traverseComponent(graph, i, visitedArray, vertexList);
+                components++;
+            }
+        }
+
+        return new TraversalResult(vertexList, components);
+    }
